import globimport pandas as pd# set a list to store all target folders''' please add folder path below '''stroop_folder = glob.glob(r"D:\github\study2\stroop-task\data\*.csv")stroop_fileslist = [file for file in stroop_folder if "practiceStroop" not in file] # ignore practice filesdata_list = []# create the for loop to append rows of each dataset to dataframefor files in range(0, len(stroop_fileslist)):    # read specific columns from data files    stroop = pd.read_csv(stroop_fileslist[files])    # create dictionaries to store values in specific cells + rename the columns names    if 'myExp.trial' in stroop.columns:        # create variables for numbers of congruent/incongruent/total trials for future calculation        congruent_num = len(stroop[stroop['myExp.congruent'] == 1])        incongruent_num = len(stroop[stroop['myExp.congruent'] == 0])        total_trials = stroop['myExp.trial'].max()        correctTrials_all = stroop.loc[(stroop['myExp.Accuracy'] == 1), 'myExp.RT_correctTrials']        correctTrials_congruent = stroop.loc[(stroop['myExp.Accuracy'] == 1) & (stroop['myExp.congruent'] == 1), 'myExp.RT_correctTrials']        correctTrials_incongruent = stroop.loc[(stroop['myExp.Accuracy'] == 1) & (stroop['myExp.congruent'] == 0), 'myExp.RT_correctTrials']        # create mean RT variables        meanRT_correct_all = correctTrials_all.mean() * 1000        meanRT_correct_congruent = correctTrials_congruent.mean() * 1000        meanRT_correct_incongruent = correctTrials_incongruent.mean() * 1000        meanRT_diff = meanRT_correct_incongruent - meanRT_correct_congruent        # create median RT variables        medianRT_correct_all = correctTrials_all.median() * 1000        medianRT_correct_congruent = correctTrials_congruent.median() * 1000        medianRT_correct_incongruent = correctTrials_incongruent.median() * 1000        medianRT_diff = medianRT_correct_incongruent - medianRT_correct_congruent        # create accuracy variables        accuracy_all = (stroop['myExp.Accuracy'].sum()/total_trials) * 100        accuracy_congruent = (stroop.loc[(stroop['myExp.congruent'] == 1), 'myExp.Accuracy'].sum() / congruent_num) * 100        accuracy_incongruent = (stroop.loc[(stroop['myExp.congruent'] == 0), 'myExp.Accuracy'].sum() / incongruent_num) * 100        # create trial duration variables        mean_trial_duration = stroop['myExp.trialDuration'].mean() * 1000        median_trial_duration = stroop['myExp.trialDuration'].median() * 1000    else:        meanRT_correct_all = meanRT_correct_congruent = meanRT_correct_incongruent = meanRT_diff = \            medianRT_correct_all = medianRT_correct_congruent = medianRT_correct_incongruent = medianRT_diff = \            accuracy_all = accuracy_congruent = accuracy_incongruent = mean_trial_duration = median_trial_duration = None    data_list.append({'participant': stroop.iloc[1]['participant'],                      'task': stroop.iloc[1]['expName'],                      'meanRT_correct_all(ms)': meanRT_correct_all,                      'meanRT_correct_congruent(ms)': meanRT_correct_congruent,                      'meanRT_correct_incongruent(ms)': meanRT_correct_incongruent,                      'meanRT_diff(ms)': meanRT_diff,                      'medianRT_correct_all(ms)': medianRT_correct_all,                      'medianRT_correct_congruent(ms)': medianRT_correct_congruent,                      'medianRT_correct_incongruent(ms)': medianRT_correct_incongruent,                      'medianRT_diff(ms)': medianRT_diff,                      'accuracy_all(%)': accuracy_all,                      'accuracy_congruent(%)': accuracy_congruent,                      'accuracy_incongruent(%)': accuracy_incongruent,                      'mean_trialDuration(ms)': mean_trial_duration,                      'median_trialDuration(ms)': median_trial_duration})stroop_data_long = pd.DataFrame(data_list)# save as csvstroop_data_long.to_csv('stroop_longFormat.csv',index=False)